385	async function ownedDomain(domainId: string) {
386	  const user = await requireUser();
387	  const domain = await db.domain.findUnique({ where: { id: domainId } });
388	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
