14	export function BackupSchedule({
15	  serverId,
16	  autoBackup,
17	  backupIntervalHours,
18	  lastAutoBackup,
19	}: {
20	  serverId: string;
21	  autoBackup: boolean;
22	  backupIntervalHours: number | null;
23	  /** ISO string of the last automatic backup, or null */
24	  lastAutoBackup: string | null;
25	}) {
26	  const [enabled, setEnabled] = useState(autoBackup);
27	  const [interval, setInterval] = useState<number>(backupIntervalHours ?? 24);
28	  const [error, setError] = useState<string | null>(null);
29	  const [saved, setSaved] = useState(false);
30	  const [pending, start] = useTransition();
31	
32	  function save(nextEnabled: boolean, nextInterval: number) {
33	    start(async () => {
34	      setError(null);
35	      setSaved(false);
36	      const res = await setBackupSchedule(serverId, nextEnabled, nextInterval);
37	      if (res?.error) {
38	        setError(res.error);
39	        setEnabled(autoBackup); // revert toggle to server truth on failure
40	      } else {
41	        setSaved(true);
42	      }
43	    });
44	  }
45	
46	  function flip() {
47	    const next = !enabled;
48	    setEnabled(next); // optimistic
49	    save(next, interval);
50	  }
51	
52	  return (
53	    <div className="card">
54	      <div className="flex flex-wrap items-start justify-between gap-4">
55	        <div>
56	          <h2 className="font-semibold">Scheduled backups</h2>
57	          <p className="mt-1 max-w-md text-sm text-slate-400">
58	            Automatically create a full-image backup on a recurring schedule. Backups land on the
59	            separate backup pool — independent from your server&apos;s NVMe storage.
60	          </p>
61	        </div>
62	        <button
63	          type="button"
64	          role="switch"
65	          aria-checked={enabled}
66	          disabled={pending}
67	          onClick={flip}
68	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
69	            enabled ? "bg-brand-500" : "bg-white/15"
70	          } ${pending ? "opacity-60" : ""}`}
71	        >
72	          <span
73	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
74	              enabled ? "translate-x-5" : "translate-x-0.5"
75	            }`}
76	          />
77	        </button>
78	      </div>
79	
80	      {enabled && (
81	        <>
82	          <div className="divider" />
83	          <label className="block text-sm">
84	            <span className="mb-1.5 block font-medium">Backup frequency</span>
85	            <select
86	              className="input"
87	              value={interval}
88	              disabled={pending}
89	              onChange={(e) => {
90	                const v = Number(e.target.value);
91	                setInterval(v);
92	                save(true, v);
93	              }}
94	            >
95	              {INTERVALS.map((i) => (
