"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import type { SslCertificate } from "@prisma/client";

/**
 * Customer SSL certificate management — one-click Let's Encrypt certs for a
 * domain the customer has already pointed at their server. Ordering is
 * ownership-checked here (at enqueue time); the actual issue runs in the worker
 * (worker/ssl.ts, SSL_ISSUE) which SSHes to the box and runs certbot — or, in
 * SANDBOX/staging, simulates a successful issue.
 */

// Basic FQDN: one or more dot-separated labels + a 2–24 char alpha TLD. Rejects
// wildcards, protocols, ports and paths — certbot wants a bare hostname.
const FQDN_RE =
  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function ownedCertificate(id: string) {
  const user = await requireUser();
  const cert = await db.sslCertificate.findUnique({ where: { id } });
  if (!cert) throw new Error("Not found");
  if (cert.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, cert };
}

/** All of the current user's SSL certificates, newest first. */
export async function listCertificates(): Promise<SslCertificate[]> {
  const user = await requireUser();
  return db.sslCertificate.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });
}

/**
 * Request a one-click Let's Encrypt certificate for `domain` on one of the
 * caller's servers. Validates the domain, checks server ownership, creates a
 * PENDING SslCertificate row and enqueues an SSL_ISSUE job (cert id in payload).
 */
export async function requestCertificate(
  serverId: string,
  domain: string
): Promise<{ error?: string; id?: string }> {
  let ctx;
  try {
    ctx = await ownedServer(serverId);
  } catch (e: any) {
    return { error: e.message };
  }
  const { user, server } = ctx;

  const clean = String(domain ?? "").toLowerCase().trim().replace(/\.$/, "");
  if (!FQDN_RE.test(clean)) {
    return { error: "Enter a valid domain name (e.g. app.example.com) — no protocol, port or wildcard." };
  }

  // One active/in-flight cert per (user, domain): don't let a customer stack
  // duplicate issue jobs for the same hostname.
  const existing = await db.sslCertificate.findFirst({
    where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
  });
  if (existing) {
    return {
      error:
        existing.status === "ACTIVE"
          ? `You already have an active certificate for ${clean}.`
          : `A certificate for ${clean} is already being issued.`,
    };
  }

  const cert = await db.sslCertificate.create({
    data: {
      userId: user.id,
      serverId: server.id,
      domain: clean,
      status: "PENDING",
      issuer: "letsencrypt",
    },
  });
  await db.job.create({
    data: { type: "SSL_ISSUE", serverId: server.id, payload: { certId: cert.id } },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "ssl.request", detail: `${clean} on ${server.hostname}` },
  });
  revalidatePath("/dashboard/ssl");
  return { id: cert.id };
}

/** Permanently remove a certificate record (owner only). */
export async function deleteCertificate(id: string): Promise<{ error?: string }> {
  let ctx;
  try {
    ctx = await ownedCertificate(id);
  } catch (e: any) {
    return { error: e.message };
  }
  if (ctx.cert.status === "ISSUING") {
    return { error: "This certificate is currently being issued — try again in a moment." };
  }
  await db.sslCertificate.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "ssl.delete", detail: `${ctx.cert.domain}` },
  });
  revalidatePath("/dashboard/ssl");
  return {};
}

/** Flip automatic renewal on/off for a certificate (owner only). */
export async function toggleAutoRenew(id: string): Promise<{ error?: string }> {
  let ctx;
  try {
    ctx = await ownedCertificate(id);
  } catch (e: any) {
    return { error: e.message };
  }
  await db.sslCertificate.update({
    where: { id },
    data: { autoRenew: !ctx.cert.autoRenew },
  });
  revalidatePath("/dashboard/ssl");
  return {};
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { Job } from "@prisma/client";

/**
 * SSL certificate issuance handler (SSL_ISSUE).
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
 *   SSL_ISSUE: sslIssue,
 *
 * Ownership + domain validation are enforced at enqueue time
 * (lib/actions-ssl.ts), so this handler trusts `payload.certId`.
 *
 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
 * VM and running certbot against a live, DNS-pointed domain. That is a real,
 * side-effecting operation, so it is DISABLED by default. Until the real path is
 * implemented and reviewed, this handler always takes the simulated-success
 * branch (which is also what SANDBOX/staging requires). No SSH is ever opened.
 */

/** A Let's Encrypt certificate is valid for 90 days. */
const CERT_LIFETIME_MS = 90 * 86400_000;

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[ssl] notify failed", e);
  }
}

export async function sslIssue(job: Job): Promise<void> {
  const payload = (job.payload ?? {}) as { certId?: string };
  if (!payload.certId) throw new Error("ssl job: missing certId");

  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);

  // Mark in-flight so the UI shows "issuing" while we work.
  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });

  try {
    // ---------------------------------------------------------------------
    // Real issuance path (SSH + certbot) — INTENTIONALLY NOT ENABLED.
    //
    // TODO(real-path): when we're ready to issue live certificates:
    //   1. Load the server (cert.serverId) and resolve its SSH endpoint
    //      (dedicated IP:22, or the platform public IP + forwarded ssh port).
    //   2. Pre-flight: confirm `cert.domain` resolves to that server's public
    //      IP (dig/getaddrinfo) so the ACME HTTP-01 challenge can succeed.
    //   3. SSH in and run certbot, e.g.:
    //        certbot certonly --non-interactive --agree-tos \
    //          -m <account-email> --webroot -w /var/www/html -d <domain>
    //      (or --standalone / an nginx plugin depending on the stack).
    //   4. Parse certbot output / read /etc/letsencrypt/live/<domain>/cert.pem
    //      for the real notAfter, and set issuedAt/expiresAt from it.
    //   5. Reload the customer's web server so the new cert is served.
    //
    // Guarded so the branch can never run accidentally: real issuance only
    // happens once ENABLE_REAL_SSL is explicitly set AND we're not in SANDBOX.
    // Until then we always fall through to the simulated success below.
    // ---------------------------------------------------------------------
    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
    if (realIssuanceEnabled) {
      // Not implemented yet — refuse rather than silently pretend.
      throw new Error("Real Let's Encrypt issuance is not implemented yet.");
    }

    // Default: simulated success (SANDBOX-safe, no SSH, no certbot).
    const now = new Date();
    await db.sslCertificate.update({
      where: { id: cert.id },
      data: {
        status: "ACTIVE",
        issuedAt: now,
        expiresAt: new Date(now.getTime() + CERT_LIFETIME_MS),
        lastError: null,
      },
    });
    await notify(
      cert.userId,
      `SSL certificate issued for ${cert.domain}`,
      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
      "/dashboard/ssl"
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 500);
    await db.sslCertificate.update({
      where: { id: cert.id },
      data: { status: "FAILED", lastError: reason },
    });
    await notify(
      cert.userId,
      `SSL certificate failed for ${cert.domain}`,
      reason.slice(0, 200),
      "/dashboard/ssl"
    );
  }
}

"use client";

import { useState, useTransition } from "react";
import { StatusDot } from "@/components/ui/primitives";
import {
  requestCertificate,
  deleteCertificate,
  toggleAutoRenew,
} from "@/lib/actions-ssl";

export type CertRow = {
  id: string;
  domain: string;
  status: string;
  issuer: string;
  autoRenew: boolean;
  serverName: string | null;
  issuedAt: string | null;
  expiresAt: string | null;
  lastError: string | null;
};

export type ServerOption = { id: string; hostname: string };

function fmtDate(iso: string | null): string {
  return iso ? new Date(iso).toISOString().slice(0, 10) : "—";
}

// ---------------------------------------------------------------------------
// Request form
// ---------------------------------------------------------------------------

function RequestCertificate({ servers }: { servers: ServerOption[] }) {
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  const [domain, setDomain] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const noServers = servers.length === 0;

  return (
    <div className="card p-5">
      <h3 className="text-base font-semibold">Request a certificate</h3>
      <p className="mt-1 text-sm text-slate-400">
        Point your domain&apos;s DNS at the server first, then request a free Let&apos;s Encrypt
        certificate. Issuance usually completes within a minute.
      </p>
      <div className="mt-4 flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Server</label>
          <select
            className="input w-52"
            value={serverId}
            onChange={(e) => setServerId(e.target.value)}
            disabled={pending || noServers}
          >
            {noServers ? (
              <option value="">No running servers</option>
            ) : (
              servers.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.hostname}
                </option>
              ))
            )}
          </select>
        </div>
        <div>
          <label className="label">Domain</label>
          <input
            className="input w-64"
            value={domain}
            onChange={(e) => setDomain(e.target.value)}
            placeholder="app.example.com"
            disabled={pending || noServers}
          />
        </div>
        <button
          className="btn-primary"
          disabled={pending || noServers || !serverId || domain.trim().length < 3}
          onClick={() =>
            start(async () => {
              setError(null);
              const res = await requestCertificate(serverId, domain.trim());
              if (res?.error) setError(res.error);
              else setDomain("");
            })
          }
        >
          {pending ? "Requesting…" : "Request certificate"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      {noServers && (
        <p className="mt-2 text-xs text-slate-500">
          You need a running server before you can request a certificate.
        </p>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Row actions (auto-renew toggle + delete)
// ---------------------------------------------------------------------------

function CertActions({ cert }: { cert: CertRow }) {
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      const res = await fn();
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="flex flex-col items-end gap-1.5">
      <div className="flex items-center gap-2">
        {error && <span className="text-xs text-red-400">{error}</span>}
        <button
          type="button"
          role="switch"
          aria-checked={cert.autoRenew}
          aria-label="Toggle auto-renew"
          disabled={pending}
          onClick={() => run(() => toggleAutoRenew(cert.id))}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            cert.autoRenew ? "bg-brand-500" : "bg-white/15"
          } ${pending ? "opacity-60" : ""}`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
              cert.autoRenew ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
        <button
          className="btn-danger px-3 py-1 text-xs"
          disabled={pending || cert.status === "ISSUING"}
          onClick={() =>
            run(
              () => deleteCertificate(cert.id),
              `Delete the certificate for "${cert.domain}"? This removes it from your account.`
            )
          }
        >
          Delete
        </button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Full manager (dashboard page)
// ---------------------------------------------------------------------------

export function SslManager({
  certificates,
  servers,
}: {
  certificates: CertRow[];
  servers: ServerOption[];
}) {
  return (
    <div className="space-y-6">
      <RequestCertificate servers={servers} />

      {certificates.length === 0 ? (
        <div className="card p-8 text-center text-sm text-slate-400">
          No certificates yet. Request one above to enable HTTPS on a domain pointed at your server.
        </div>
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Domain</th>
                <th>Server</th>
                <th>Status</th>
                <th>Expires</th>
                <th>Auto-renew &amp; actions</th>
              </tr>
            </thead>
            <tbody>
              {certificates.map((c) => (
                <tr key={c.id}>
                  <td className="font-medium text-slate-100">
                    {c.domain}
                    {c.status === "FAILED" && c.lastError && (
                      <span className="mt-0.5 block text-xs font-normal text-red-400">
                        {c.lastError}
                      </span>
                    )}
                  </td>
                  <td className="text-slate-400">{c.serverName ?? "—"}</td>
                  <td>
                    <StatusDot status={c.status} />
                  </td>
                  <td className="text-slate-400">{fmtDate(c.expiresAt)}</td>
                  <td>
                    <CertActions cert={c} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageHeader } from "@/components/ui/primitives";
import { SslManager, type CertRow, type ServerOption } from "@/components/customer/SslManager";

export const dynamic = "force-dynamic";

export default async function SslPage() {
  const user = await requireUser();

  const [certificates, servers] = await Promise.all([
    db.sslCertificate.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
    db.server.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));

  const rows: CertRow[] = certificates.map((c) => ({
    id: c.id,
    domain: c.domain,
    status: c.status,
    issuer: c.issuer,
    autoRenew: c.autoRenew,
    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
    lastError: c.lastError,
  }));

  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
  const serverOptions: ServerOption[] = servers
    .filter((s) => s.status === "RUNNING")
    .map((s) => ({ id: s.id, hostname: s.hostname }));

  const transitional = certificates.some((c) => ["PENDING", "ISSUING"].includes(c.status));

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PageHeader
        title="SSL Certificates"
        sub="One-click Let's Encrypt certificates for domains pointed at your servers."
      />
      <SslManager certificates={rows} servers={serverOptions} />
    </div>
  );
}

